        && outcome.severity > Severity::None
    {
        agg.add(
            &pkg.id,
            outcome.severity,
            Source::Inference {
                commits: outcome.commit_count,
                remapped: outcome.remapped,
            },
        );
        agg.inference_commits.insert(pkg.id.clone(), outcome.commits.clone());
